// PaymentServiceServer is the server API for PaymentService service.
// All implementations must embed UnimplementedPaymentServiceServer
// for forward compatibility.
type PaymentServiceServer interface {
	// Stripe onboarding
	CreateStripeAccount(context.Context, *CreateStripeAccountRequest) (*CreateStripeAccountResponse, error)
	GetStripeOnboardingLink(context.Context, *GetStripeOnboardingLinkRequest) (*GetStripeOnboardingLinkResponse, error)
	GetStripeAccountStatus(context.Context, *GetStripeAccountStatusRequest) (*GetStripeAccountStatusResponse, error)
	GetStripeDashboardLink(context.Context, *GetStripeDashboardLinkRequest) (*GetStripeDashboardLinkResponse, error)
	// Customer payment methods
	CreateSetupIntent(context.Context, *CreateSetupIntentRequest) (*CreateSetupIntentResponse, error)
	ListPaymentMethods(context.Context, *ListPaymentMethodsRequest) (*ListPaymentMethodsResponse, error)
	DeletePaymentMethod(context.Context, *DeletePaymentMethodRequest) (*DeletePaymentMethodResponse, error)
	// AddDevPaymentMethod is dev-only — it bypasses Stripe Elements and
	// inserts a card directly into the in-memory dev store. Gateway gates this
	// behind a dev-mode check; production returns FailedPrecondition.
	AddDevPaymentMethod(context.Context, *AddDevPaymentMethodRequest) (*AddDevPaymentMethodResponse, error)
	// Payments
	CreatePayment(context.Context, *CreatePaymentRequest) (*CreatePaymentResponse, error)
	ProcessPayment(context.Context, *ProcessPaymentRequest) (*ProcessPaymentResponse, error)
	ReleaseEscrow(context.Context, *ReleaseEscrowRequest) (*ReleaseEscrowResponse, error)
	GetPayment(context.Context, *GetPaymentRequest) (*GetPaymentResponse, error)
	ListPayments(context.Context, *ListPaymentsRequest) (*ListPaymentsResponse, error)
	// Refunds
	CreateRefund(context.Context, *CreateRefundRequest) (*CreateRefundResponse, error)
	// Webhooks
	HandleStripeWebhook(context.Context, *HandleStripeWebhookRequest) (*HandleStripeWebhookResponse, error)
	// Platform fees
	CalculateFees(context.Context, *CalculateFeesRequest) (*CalculateFeesResponse, error)
	GetFeeConfig(context.Context, *GetFeeConfigRequest) (*GetFeeConfigResponse, error)
	// Admin
	AdminGetPaymentDetails(context.Context, *AdminGetPaymentDetailsRequest) (*AdminGetPaymentDetailsResponse, error)
	AdminListPayments(context.Context, *AdminListPaymentsRequest) (*AdminListPaymentsResponse, error)
	AdminUpdateFeeConfig(context.Context, *AdminUpdateFeeConfigRequest) (*AdminUpdateFeeConfigResponse, error)
	// Platform banking (admin) — the platform's own payout bank account where
	// all collected fees route. Raw bank numbers never reach us: the client
	// tokenizes via Stripe.js and sends a bank_account token.
	AdminGetPlatformBankAccount(context.Context, *AdminGetPlatformBankAccountRequest) (*AdminGetPlatformBankAccountResponse, error)
	AdminSetPlatformBankAccount(context.Context, *AdminSetPlatformBankAccountRequest) (*AdminSetPlatformBankAccountResponse, error)
	AdminDeletePlatformBankAccount(context.Context, *AdminDeletePlatformBankAccountRequest) (*AdminDeletePlatformBankAccountResponse, error)
	// Revenue reporting
	GetRevenueReport(context.Context, *GetRevenueReportRequest) (*GetRevenueReportResponse, error)
	// Expenses
	CreateExpense(context.Context, *CreateExpenseRequest) (*CreateExpenseResponse, error)
	ListExpenses(context.Context, *ListExpensesRequest) (*ListExpensesResponse, error)
	DeleteExpense(context.Context, *DeleteExpenseRequest) (*DeleteExpenseResponse, error)
	// Working Capital
	RequestAdvance(context.Context, *RequestAdvanceRequest) (*RequestAdvanceResponse, error)
	ListAdvances(context.Context, *ListAdvancesRequest) (*ListAdvancesResponse, error)
	GetAdvance(context.Context, *GetAdvanceRequest) (*GetAdvanceResponse, error)
	ReviewAdvance(context.Context, *ReviewAdvanceRequest) (*ReviewAdvanceResponse, error)
	DisburseAdvance(context.Context, *DisburseAdvanceRequest) (*DisburseAdvanceResponse, error)
	GetCreditLimit(context.Context, *GetCreditLimitRequest) (*GetCreditLimitResponse, error)
	// BNPL Installment Plans
	CreateInstallmentPlan(context.Context, *CreateInstallmentPlanRequest) (*CreateInstallmentPlanResponse, error)
	GetInstallmentPlan(context.Context, *GetInstallmentPlanRequest) (*GetInstallmentPlanResponse, error)
	ListInstallmentPlans(context.Context, *ListInstallmentPlansRequest) (*ListInstallmentPlansResponse, error)
	// Insurance
	ListInsuranceProducts(context.Context, *ListInsuranceProductsRequest) (*ListInsuranceProductsResponse, error)
	GetInsuranceQuote(context.Context, *GetInsuranceQuoteRequest) (*GetInsuranceQuoteResponse, error)
	PurchaseInsurance(context.Context, *PurchaseInsuranceRequest) (*PurchaseInsuranceResponse, error)
	GetInsurancePolicy(context.Context, *GetInsurancePolicyRequest) (*GetInsurancePolicyResponse, error)
	ListInsurancePolicies(context.Context, *ListInsurancePoliciesRequest) (*ListInsurancePoliciesResponse, error)
	FileInsuranceClaim(context.Context, *FileInsuranceClaimRequest) (*FileInsuranceClaimResponse, error)
	GetInsuranceClaim(context.Context, *GetInsuranceClaimRequest) (*GetInsuranceClaimResponse, error)
	ReviewInsuranceClaim(context.Context, *ReviewInsuranceClaimRequest) (*ReviewInsuranceClaimResponse, error)
	AdminListInsuranceClaims(context.Context, *AdminListInsuranceClaimsRequest) (*AdminListInsuranceClaimsResponse, error)
	// Tax Forms
	GenerateTaxForm(context.Context, *GenerateTaxFormRequest) (*GenerateTaxFormResponse, error)
	GetTaxForm(context.Context, *GetTaxFormRequest) (*GetTaxFormResponse, error)
	ListTaxForms(context.Context, *ListTaxFormsRequest) (*ListTaxFormsResponse, error)
	// Invoices
	GenerateInvoice(context.Context, *GenerateInvoiceRequest) (*GenerateInvoiceResponse, error)
	// Tax form / invoice HTML retrieval
	GetTaxFormHTML(context.Context, *GetTaxFormHTMLRequest) (*GetTaxFormHTMLResponse, error)
	GetInvoiceHTML(context.Context, *GetInvoiceHTMLRequest) (*GetInvoiceHTMLResponse, error)
	// ============================================================
	// Marketplace (peer-to-peer goods) — escrow + pickup + release
	// ============================================================
	// Lifecycle: pending_payment -> held -> pickup_confirmed -> released
	// (with optional disputed branch). See docs/operations/marketplace-escrow.md
	// for the state diagram and dispute timeline.
	ChargeListingWinner(context.Context, *ChargeListingWinnerRequest) (*ChargeListingWinnerResponse, error)
	ConfirmListingPickup(context.Context, *ConfirmListingPickupRequest) (*ConfirmListingPickupResponse, error)
	FileListingDispute(context.Context, *FileListingDisputeRequest) (*FileListingDisputeResponse, error)
	ResolveListingDispute(context.Context, *ResolveListingDisputeRequest) (*ResolveListingDisputeResponse, error)
	AutoReleaseListingOrders(context.Context, *AutoReleaseListingOrdersRequest) (*AutoReleaseListingOrdersResponse, error)
	// GDPR — delete a customer's Stripe Customer + Connect Express account.
	// Called by the user service's Erasure pipeline after the local DB cascade
	// commits. Outcomes are recorded verbatim in the user service's audit log.
	// See docs/operations/gdpr-delete.md.
	DeleteStripeAccounts(context.Context, *DeleteStripeAccountsRequest) (*DeleteStripeAccountsResponse, error)
	mustEmbedUnimplementedPaymentServiceServer()
}

